TLM.f("Tempora/Pasc0-6",{"officium":"Sabbato in Albis","rule":["ex Pasc0-0;","Credo","Sequentia","Suffr=Ecclesiæ,Papa;;"],"ruleInherited":["Sequentia","Credo","Prefatio=Pasch"],"fallback":"Tempora/Pasc0-0","sections":{"Introitus":[{"k":"ref","la":"Ps 104:43"},{"k":"text","la":"Edúxit Dóminus pópulum suum in exsultatióne, allelúja: et eléctos suos in lætítia, allelúja, allelúja."},{"k":"ref","la":"Ps 104:1"},{"k":"text","la":"Confitémini Dómino et invocáte nomen ejus: annuntiáte inter gentes ópera ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Edúxit Dóminus pópulum suum in exsultatióne, allelúja: et eléctos suos in lætítia, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Concéde, quǽsumus, omnípotens Deus: ut, qui festa paschália venerándo égimus, per hæc contíngere ad gáudia ætérna mereámur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Petri Apóstoli"},{"k":"ref","la":"1 Pet 2:1-10"},{"k":"text","la":"Caríssimi: Deponéntes ígitur omnem malítiam, et omnem dolum, et simulatiónes, et invídias, et omnes detractiónes, sicut modo géniti infántes, rationábile, sine dolo lac concupíscite: ut in eo crescátis in salútem: si tamen gustástis, quóniam dulcis est Dóminus. Ad quem accedéntes lápidem vivum, ab homínibus quidem reprobátum, a Deo autem eléctum et honorificátum: et ipsi tamquam lápides vivi superædificámini, domus spirituális, sacerdótium sanctum, offérre spirituáles hóstias, acceptábiles Deo per Jesum Christum. Propter quod cóntinet Scriptúra: Ecce, pono in Sion lápidem summum angulárem, eléctum, pretiósum: et qui credíderit in eum, non confundátur. Vobis ígitur honor credéntibus: non credéntibus autem lapis, quem reprobavérunt ædificántes, hic factus est in caput ánguli, et lapis offensiónis, et petra scándali his, qui offéndunt verbo, nec credunt in quo et pósiti sunt. Vos autem genus eléctum, regále sacerdótium, gens sancta, pópulus acquisitiónis: ut virtútes annuntiétis ejus, qui de ténebris vos vocávit in admirábile lumen suum. Qui aliquándo non pópulus, nunc autem pópulus Dei: qui non consecúti misericórdiam, nunc autem misericórdiam consecúti."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 117:24"},{"k":"text","la":"Hæc dies, quam fecit Dóminus: exsultémus et lætémur in ea. Allelúja."},{"k":"ref","la":"Ps 112:1"},{"k":"text","la":"Laudáte, púeri, Dóminum, laudáte nomen Dómini."},{"k":"sep"},{"k":"rubric","la":"Ab hoc die usque ad Sabbatum Quatuor Temporum Pentecostes inclusive, in omnibus Missis, non dicitur Graduale sed quatuor Allelúja cum duobus Versibus, ordine infrascripto; in Missa tamen Rogationum, in Vigilia Pentecostes et post quamlibet Lectionem in Sabbato Quatuor Temporum ejusdem, unum Allelúja dicitur cum unico Versu."}],"Sequentia":[{"k":"text","la":"Víctimæ pascháli laudes ímmolent Christiáni."},{"k":"text","la":"Agnus rédemit oves: Christus ínnocens Patri reconciliávit peccatóres."},{"k":"text","la":"Mors et vita duéllo conflixére mirándo: dux vitæ mórtuus regnat vivus."},{"k":"text","la":"Dic nobis, María, quid vidísti in via?"},{"k":"text","la":"Sepúlcrum Christi vivéntis et glóriam vidi resurgéntis."},{"k":"text","la":"Angélicos testes, sudárium et vestes."},{"k":"text","la":"Surréxit Christus, spes mea: præcédet vos in Galilǽam."},{"k":"text","la":"Scimus Christum surrexísse a mórtuis vere: tu nobis, victor Rex, miserére. Amen. Allelúja."},{"k":"rubric","la":"Sequentia dicitur usque ad Sabbatum in Albis inclusive."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem."},{"k":"ref","la":"Joannes 20:1-9"},{"k":"text","la":"In illo témpore: Una sábbati, María Magdaléne venit mane, cum adhuc ténebræ essent, ad monuméntum: et vidit lápidem sublátum a monuménto. Cucúrrit ergo, et venit ad Simónem Petrum, et ad álium discípulum, quem amábat Jesus, et dicit illis: Tulérunt Dóminum de monuménto, et nescímus, ubi posuérunt eum. Exiit ergo Petrus et ille álius discípulus, et venérunt ad monuméntum. Currébant autem duo simul, et ille álius discípulus præcucúrrit cítius Petro, et venit primus ad monuméntum. Et cum se inclinásset, vidit pósita linteámina, non tamen introívit. Venit ergo Simon Petrus sequens eum, et introívit in monuméntum, et vidit linteámina pósita, et sudárium, quod fúerat super caput ejus, non cum linteamínibus pósitum, sed separátim involútum in unum locum. Tunc ergo introívit et ille discípulus, qui vénerat primus ad monuméntum: et vidit et crédidit: nondum enim sciébant Scriptúram, quia oportébat eum a mórtuis resúrgere."}],"Offertorium":[{"k":"ref","la":"Ps 7:26-27"},{"k":"text","la":"Benedíctus, qui venit in nómine Dómini: benedíximus vobis de domo Dómini: Deus Dóminus, et illúxit nobis, allelúja, allelúja."}],"Secreta":[{"k":"text","la":"Concéde, quǽsumus, Dómine, semper nos per hæc mystéria paschália gratulári: ut contínua nostræ reparatiónis operátio perpétuæ nobis fiat causa lætítiæ."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Gal 3:27"},{"k":"text","la":"Omnes, qui in Christo baptizáti estis, Christum induístis, allelúja."}],"Postcommunio":[{"k":"text","la":"Redemptiónis nostræ múnere vegetáti, quǽsumus, Dómine: ut, hoc perpétuæ salútis auxílio, fides semper vera profíciat."},{"k":"macro","name":"Per Dominum"}]},"hr":{"fa0b7971a5990fe4":{"t":"Ps 104, 43, Ps 104, 1\n(Ps 104, 43) Izveo je Gospodin puk svoj u klicanju, <i>aleluja</i>,\ni izabrane svoje u radosti, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 104, 1) Slavite Gospodina i zazivajte ime njegovo, navještajte među narodima djela njegova.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 104, 43) Izveo je Gospodin puk svoj u klicanju, <i>aleluja</i>,\ni izabrane svoje u radosti, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 104, 43). Izveo je Gospodin puk svoj u klicanju, aleluja, i izabrane svoje u radosti, aleluja, aleluja. (Ps. 104, 1). Slavite Gospodina 1 zazivajte ime njegovio, naviještajte među narodima djela njegova. Slava Ocu . . . Izveo je . . .","knRef":"Kniewald 1942, str. 314–315 (snimka 158) (OCR)"},"524190303272b8bf":{"t":"<i>Pomolimo se</i>.\nDopusti, molimo, svemogući Bože, da mi koji smo časno proslavili uskrsne svetkovine po njima zaslužimo doći do vječnih radosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Dopusti, molimo, svemogući Bože, da ml, koji -smo časno sproveli uskrsne svetkovine, po njima zaslužimo' doći do vječnih radosti, po G. rt.","knRef":"Kniewald 1942, str. 314–315 (snimka 158) (OCR)"},"f45c5b46fa6c4594":{"t":"1 Pt 2, 1-10\nČitanje Poslanice bl. Petra apostola. Predragi! Odbacite svaku zlobu i svaku lukavštvinu i himbu i zavist i svako klevetanje. Želite kao novorođena djeca duhovnoga i čistoga mlijeka da u njem uzrastete za spasenje, ako li ste okusili, kako je blag Gospodin. Pristupite dakle k njemu kamenu živome koji je doduše od ljudi odbačen, ali je od Boga izabran i predragocjen. I sami kao živo kamenje uzidajte se kao kuća duhovna i svećenstvo sveto da prinosite žrtve duhovne, predrage Bogu po Isusu Kristu. Zato stoji u Pismu: Evo stavljam na Sionu kamen ugaoni, izabrani, dragocjeni, i koji vjeruje u njega neće se posramiti. Vama je, dakle, vjernicima Gospodin na čast, a nevjernicima kamen koji odbaciše graditelji i taj posta glava od ugla i kamen spoticaja i pećina sablazni na koji se spotiču koji ne vjeruju riječi na što su i određeni. Ali vi ste rod izabrani, kraljevsko svećenstvo, sveti narod, puk stečeni, da proglasite kreposti onoga koji vas pozva iz tame k divnom svjetlu svome. Nekad ne bijaste puk, a sada ste puk Božji, nekad ne bijaste pomilovani, a sad ste pomilovani.","kn":"Čitanje poslanice bi. Petra apostola (I, 2, 1-10). Predragi! Odbacite svaku zlobu, 1 svaku lukavštihu, i himbu, i zavist, i svako klevetanje. Želite kao novorođena djeca duhovnoga i čistoga mlijeka, da ti njem uzrastete za spasenje, ako U ste okusili, je blag Gospodin. Pristupite daikle k njemu, kamenu živome, koji je doduše od ljudi O'dbačen, ali je od Boga izabran i predragocjen. I sami kao živo kamenje uzidajte se kao kuća duhovna i svećenstvo sveto, da' prinosite žrtve duhovne, predrage Bogu po Isusu Kristu. Zato stoji u Pismu: »Evo stavljam na ’Sionu kamen ugaoni, izabrani, dragocjeni, i koji vjeruje u njega, ne će se posramiti«. ^ Vama je dakle, vjernicima, (Gospodin) na čast, a nevjernicima kamen, koji odbaciše graditelji, i taj posta glava od ugla, 1 kamen spoticaja,, i pećina sablazni, na koji .se spotiču, koji ne vjeruju riječi, na što su i određeni. Alj vi ste rod izabrani, kraljevsko svećenstV'O, sveti narod, puk stečeni, da proglasite kreposti onoga, koji vas pozna iz tame k divnom svijetlu svomu; koji nekad ne bijaste puk, a sad ste puk Božji, koji ne bijaste pomilovani, a sad ste porhilovani.","knRef":"Kniewald 1942, str. 314–315 (snimka 158) (OCR)"},"202203b7daa4ce83":{"t":"Ps 117, 24, Ps 112, 1\n<i>Aleluja</i>, <i>aleluja</i>.\nOvo je dan što ga učini Gospodin, kličimo i radujmo se danas! <i>Aleluja</i>.\nHvalite, djeco, Gospodina, hvalite ime Gospodnje.","kn":"Aleluja, aleluja (Ps. 117, 24). Ovo je dan, koji nam je pripravio Gospodin, kličimo i radujmo se! Alelu'ja (Ps. 112, 1). Hvalite, djeco. Gospodina, hvalite ime Gospodnje.","knRef":"Kniewald 1942, str. 314–315 (snimka 158) (OCR)"},"a670bd50efcad44c":{"t":"Svetoj Žrtvi uskrsnici dajte slavu krštenici!<i>\n</i>\nJanje ovce oslobodi Krist nas grješne preporodi.<i>\n</i>\nSa životom smrt se sasta i čudesna borba nasta: Vođa živih pade tada i živ živcat opet vlada.<i>\n</i>\nMarijo, o reci što je? Što ti oko vidjelo je?<i>\n</i>\nGrob ja vidjeh Krista Boga, svijetlu slavu uskrsloga.<i>\n</i>\nAnđele i platno bijelo u kom bješe sveto tijelo.<i>\n</i>\nUfanje mi uskrslo je Krist, moj Gospod i sve moje! Pred vama će tamo gdje je cvjetna strana Galileje.<i>\n</i>\nZnamo da si doistine uskrsnuo Božji Sine! Pobjedniče, Kralju divan, budi nama milostivan!<i>\n</i>\n<i>amen</i>, <i>aleluja</i>."},"77141ae08f63a75f":{"t":"Iv 20, 1-9\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme, u prvi dan sedmice, dođe Marija Magdalena na grob rano, dok je još bila tama, i vidi da je kamen odvaljen od groba. Onda potrči i dođe k Šimunu Petru i k drugome učeniku koga je Isus ljubio i kaže im: Uzeše Gospodina iz groba i ne znamo gdje ga metnuše. Iziđe dakle i Petar i drugi učenik i pođoše ka grobu. A trčali su oba zajedno, i drugi je učenik trčao brže od Petra i došao prije ka grobu. I sagnuvši se vidi platno gdje leži, ali ne uđe. Dođe dakle i Šimun Petar idući za njim i uđe u grob, i vidi platno gdje leži, i ručnik koji je bio na glavi njegovoj, gdje ne leži s drugim platnom, nego napose savit na jednom mjestu. Tada dakle uđe i drugi učenik koji dođe prvi ka grobu i vidje i vjerova, jer još nisu razumjeli Pisma da mu je trebalo uskrsnuti od mrtvih.","kn":"t Slijedi sv. evanđelje po Ivanu (20, 1-9), tJ ono vrijeme, u prvi dan sedmice, dođe Marija Magdalena na grob rano, dok je još bila tama, i vidi, da je kamen odvaljen od groba. Onda potrči i dođe k Simunu-Petru i k drugome učeniku, koga je Isus ljubio, i kaže im; Uzeše Gospodina iz groba, l ne znamo, gdje ga metnuše. Iziđe dakle i Petar i drugi učenik, i pođoše ka groibu. A trčali su oba zajedno, i drugi je učenik trčao brže od Petra i došaio prijff ka grobu, I sagnuvši se vidi platno, gdje leži, ali ne uđe. Dođe. dakle i Simuin Petar idući za njim i uđe u grob, i vidi platno gdje leži, i ručnik, koji je bio na glavi njegovoj, gdje ne leži s drugim platnom, nego napose savit na jednom mjestu. Tada dakle uđe i drugi učenik, koji dođe prvi ka grobu, i vidje i vjerova, jer još nisu razumjeli Pisma, da mu je trebalo uskrsnutl od mrtvih.","knRef":"Kniewald 1942, str. 316–317 (snimka 159) (OCR)"},"f21a206a6fcd5eac":{"t":"Ps 117, 26-27\nBlagoslovljen koji dolazi u ime Gospodnje; blagoslivljamo vas iz doma Gospodnjega, Bog je Gospodin, on nas je obasjao, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 117, 26, 27). Blagoslovljen, koji dolazi u ime Gospodnje; blagosivamo vas iz doma Gospodnjega, Bog je Gospodin, on nas je obasjao, aleluja, aleluja.","knRef":"Kniewald 1942, str. 316–317 (snimka 159) (OCR)"},"36abb1bb2cab13e1":{"t":"Dopusti, molimo, Gospodine, da se uvijek ponosimo ovim uskrsnim tajnama te nam neprestano djelovanje našeg otkupljenja bude uzrokom vječnog veselja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Dopusti, molimo, Gospodine, da se uvijek ponosimo ovim vazmenim tajnama, te nam neprestano djelovanje našeg otkupljenja bude uzrokom vječnog veselja, po G. n. iPređsIovIje uskrsno.","knRef":"Kniewald 1942, str. 316–317 (snimka 159) (OCR)"},"687cae1ead8b8c38":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>danas</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"j Uistinu je dostojno i pravedno, pravo i spaso- I doba, ali osobito svečano na - današnji dan, (u ovo vrijeme), kad je žrtvovano naše vazmeno Janje, I Isukrst; jer On je pravo janje, koje je uzelo grijehe : svojim je uskrsnućem obnovio naš ž^vot. Zato pje- I vamo pjesmu Tvoje slave s anđelima i s arkanđe lima, s. prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"aed69547681ebd0d":{"t":"Gal 3, 27\nSvi koji ste se u Kristu krstili, Krista ste obukli, <i>aleluja</i>.","kn":"(Gal, 3,27). Svi, koji ste se u Kristu pokrstili, Krista se obukli, aleluja.","knRef":"Kniewald 1942, str. 316–317 (snimka 159) (OCR)"},"c4cfab681aef848f":{"t":"<i>Pomolimo se</i>.\nRedemptiónis nostrae múnere vegetáti, quaésumus, Dómine: ut hoc perpétuae salútis auxílio fides semper vera profíciat.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
